/*
 * jalf-cards.js — JALF themed card renderer (plain JS, no build step)
 * Depends on: cardmeister.full.js loaded BEFORE this file via a <script src> tag.
 *   (cardmeister registers the <playing-card> element and MUST be a separate
 *    external file — it reads its own script URL, so it cannot be inlined.)
 *
 * Usage in your game:
 *   <script src="cardmeister.full.js"></script>
 *   <script src="jalf-cards.js"></script>
 *   <script>
 *     JALFCards.setTheme("Casino Green");        // pick any theme name
 *     document.body.appendChild(JALFCards.renderCard("A","S"));  // Ace of spades, face up
 *     document.body.appendChild(JALFCards.renderBack());          // themed card back
 *   </script>
 *
 * Themes can also be loaded from themes.json instead of the built-in copy:
 *   fetch("themes.json").then(r=>r.json()).then(t=>JALFCards.loadThemes(t));
 */
(function (global) {
  "use strict";

  // Built-in themes (same data as themes.json). Edit here or call loadThemes().
  var THEMES = {
    "Classic":{card:"#ffffff",border:"#1a2e5a",suit:"#1b2430,#c62828,#c62828,#1b2430",court:"#DB3,#c62828,#1b2430,#1b2430,#000,4"},
    "JALF Green":{card:"#f4f7fb",border:"#22a63f",suit:"#1a2e5a,#22a63f,#22a63f,#1a2e5a",court:"#22a63f,#22a63f,#1a2e5a,#1a2e5a,#1a2e5a,4"},
    "Rose Gold":{card:"#fff5f2",border:"#c98a6d",suit:"#6b4a3a,#c25b4e,#c25b4e,#6b4a3a",court:"#c98a6d,#c25b4e,#6b4a3a,#6b4a3a,#6b4a3a,4"},
    "Casino Green":{card:"#0e4429",border:"#d9b34a",suit:"#f4ecd6,#d9b34a,#d9b34a,#f4ecd6",court:"#d9b34a,#d9b34a,#0a3320,#0a3320,#0a3320,4"},
    "Slate & Amber":{card:"#e7e9ec",border:"#3a3f47",suit:"#2b2f36,#e0902a,#e0902a,#2b2f36",court:"#e0902a,#e0902a,#2b2f36,#2b2f36,#2b2f36,4"},
    "Ivory & Burgundy":{card:"#f5efe2",border:"#7a1f2b",suit:"#2e2620,#8e2433,#8e2433,#2e2620",court:"#b08d3c,#8e2433,#2e2620,#2e2620,#2e2620,4"},
    "Monochrome":{card:"#f7f7f5",border:"#2a2a2a",suit:"#2a2a2a,#7a7a7a,#7a7a7a,#2a2a2a",court:"#9a9a9a,#7a7a7a,#2a2a2a,#2a2a2a,#2a2a2a,4"}
  };

  var LOGO_SRC = "data:image/png;base64,";

  var SUITS = ["S","H","D","C"];
  var RANKS = ["A","2","3","4","5","6","7","8","9","T","J","Q","K"];

  var currentTheme = "JALF Green";
  var stylesInjected = false;

  // Inject the .card-back CSS once. The two colours are set per-element inline.
  function injectStyles() {
    if (stylesInjected) return;
    var css =
      ".jalf-card-back{width:104px;aspect-ratio:5/7;border-radius:9px;" +
      "background:var(--back-outer);border:2px solid var(--back-outer);" +
      "display:flex;align-items:center;justify-content:center;padding:3px;" +
      "box-sizing:border-box;filter:drop-shadow(0 6px 12px rgba(0,0,0,.45));}" +
      ".jalf-card-back-inner{width:100%;height:100%;background:var(--back-inner);" +
      "border-radius:5px;display:flex;align-items:center;justify-content:center;padding:6px 5px;box-sizing:border-box;}" +
      ".jalf-card-back-inner img{max-width:100%;max-height:100%;object-fit:contain;}";
    var s = document.createElement("style");
    s.textContent = css;
    document.head.appendChild(s);
    stylesInjected = true;
  }

  function theme() {
    var t = THEMES[currentTheme];
    if (!t) throw new Error("JALFCards: unknown theme '" + currentTheme + "'");
    return t;
  }

  // Public API ---------------------------------------------------------------

  function loadThemes(obj) { THEMES = obj; return API; }

  function setTheme(name) {
    if (!THEMES[name]) throw new Error("JALFCards: unknown theme '" + name + "'");
    currentTheme = name;
    return API;
  }

  function getTheme() { return currentTheme; }
  function themeNames() { return Object.keys(THEMES); }

  // Face-up card. rank in RANKS (use "T" for ten), suit in SUITS.
  function renderCard(rank, suit) {
    var t = theme();
    var el = document.createElement("playing-card");
    el.setAttribute("cid", rank + String(suit).toLowerCase());
    el.setAttribute("cardcolor", t.card);
    el.setAttribute("suitcolor", t.suit);
    el.setAttribute("rankcolor", t.suit);   // rank letters match the pips
    el.setAttribute("courtcolors", t.court);
    el.setAttribute("opacity", "1");
    el.setAttribute("bordercolor", t.border);
    el.setAttribute("borderline", "3");
    return el;
  }

  // Themed card back: outer border = face colour, inner panel = border colour.
  function renderBack() {
    injectStyles();
    var t = theme();
    var back = document.createElement("div");
    back.className = "jalf-card-back";
    back.style.setProperty("--back-outer", t.card);
    back.style.setProperty("--back-inner", t.border);
    back.innerHTML = '<div class="jalf-card-back-inner"><img alt="JALF" src="' + LOGO_SRC + '"></div>';
    return back;
  }

  // Helpers your game may want.
  function fullDeck() {
    var d = [];
    for (var i=0;i<SUITS.length;i++) for (var j=0;j<RANKS.length;j++) d.push({r:RANKS[j], s:SUITS[i]});
    return d;
  }
  function shuffle(a) {
    for (var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var tmp=a[i];a[i]=a[j];a[j]=tmp;}
    return a;
  }
  function scoreHand(cards) {
    var t=0, ace=0;
    for (var i=0;i<cards.length;i++){
      var r=cards[i].r;
      if (r==="A"){t+=11;ace++;}
      else if (r==="T"||r==="J"||r==="Q"||r==="K") t+=10;
      else t+=parseInt(r,10);
    }
    while (t>21 && ace>0){t-=10;ace--;}
    return t;
  }

  var API = {
    SUITS: SUITS, RANKS: RANKS,
    loadThemes: loadThemes, setTheme: setTheme, getTheme: getTheme, themeNames: themeNames,
    renderCard: renderCard, renderBack: renderBack,
    fullDeck: fullDeck, shuffle: shuffle, scoreHand: scoreHand
  };

  global.JALFCards = API;
})(window);
